<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PayrollController {public function index(Request $r){$q=DB::table('payroll')->join('employees','payroll.employee_id','=','employees.id')->select('payroll.*','employees.full_name','employees.employee_no');if($r->filled('status'))$q->where('payroll.status',$r->string('status'));return $q->orderByDesc('pay_period_end')->paginate($r->integer('per_page',20));}public function store(Request $r){$d=$r->validate(['employee_id'=>'required|integer','pay_period_start'=>'required|date','pay_period_end'=>'required|date','regular_hours'=>'required|numeric|min:0','overtime_hours'=>'required|numeric|min:0','allowances'=>'nullable|numeric|min:0','bonuses'=>'nullable|numeric|min:0','deductions'=>'nullable|numeric|min:0']);$e=DB::table('employees')->find($d['employee_id']);abort_unless($e,404);$basic=$e->pay_type==='Hourly'?$d['regular_hours']*$e->hourly_rate:$e->basic_salary/2;$ot=$d['overtime_hours']*$e->hourly_rate*1.25;$net=$basic+$ot+($d['allowances']??0)+($d['bonuses']??0)-($d['deductions']??0);$id=DB::table('payroll')->insertGetId($d+['basic_salary'=>$basic,'hourly_rate'=>$e->hourly_rate,'overtime_pay'=>$ot,'net_pay'=>$net,'status'=>'Draft','created_by'=>$r->user()->username]);return response()->json(DB::table('payroll')->find($id),201);}public function review(Request $r,int $payroll){$d=$r->validate(['decision'=>'required|in:Approved,Paid','notes'=>'nullable|string|max:500']);DB::table('payroll')->where('id',$payroll)->update(['status'=>$d['decision'],'approved_by'=>$r->user()->username,'paid_at'=>$d['decision']==='Paid'?now()->format('Y-m-d H:i:s'):null]);return DB::table('payroll')->find($payroll);}}